var i=`0082-tochitura`;var n=`world-0082`;var a=`RO`;var o=`eastern-europe`;var s=4;var r=72;var l={en:`Tochitură`,ua:`Токітура`};var d={en:`A classic dish from Romania, featuring pork shoulder, yellow onion, garlic, tomato. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: свиняча лопатка, жовта цибуля, часник, помідор. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`pork-shoulder`,650,`g`],[`lard`,40,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`garlic`,5,`clove`],[`tomato`,200,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 45 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 45 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:45,i:[[`dry-red-wine`,110,`ml`],[`water`,380,`ml`],[`bay-leaf`,2,`leaf`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,15,`g`]]}];var g={slug:i,id:n,country:`RO`,region:o,servings:4,minutes:72,title:l,text:d,steps:u};export{a as country,g as default,n as id,r as minutes,o as region,s as servings,i as slug,u as steps,d as text,l as title};